/**
 * Security utilities for WebView operations
 */

import { WebViewMessage, MessageFilter, SecurityError } from '../types'

export class SecurityUtils {
  private static readonly ALLOWED_PROTOCOLS = ['http:', 'https:', 'data:', 'blob:']
  private static readonly DANGEROUS_PATTERNS = [
    /javascript:/i,
    /vbscript:/i,
    /data:text\/html/i,
    /<script/i,
    /eval\s*\(/i,
    /Function\s*\(/i
  ]

  /**
   * Validate URL for iframe loading
   */
  static validateUrl(url: string): boolean {
    try {
      const parsed = new URL(url)

      // Check protocol
      if (!this.ALLOWED_PROTOCOLS.includes(parsed.protocol)) {
        return false
      }

      // Check for dangerous patterns
      if (this.DANGEROUS_PATTERNS.some(pattern => pattern.test(url))) {
        return false
      }

      return true
    } catch (error) {
      return false
    }
  }

  /**
   * Validate message origin against trusted origins
   */
  static validateOrigin(origin: string, trustedOrigins: string[]): boolean {
    if (!trustedOrigins.length) {
      return true // No restrictions
    }

    // Exact match
    if (trustedOrigins.includes(origin)) {
      return true
    }

    // Wildcard pattern matching
    return trustedOrigins.some(trusted => {
      if (trusted.includes('*')) {
        const pattern = trusted.replace(/\*/g, '.*')
        const regex = new RegExp(`^${pattern}$`, 'i')
        return regex.test(origin)
      }
      return false
    })
  }

  /**
   * Validate WebView message structure and content
   */
  static validateMessage(message: any): message is WebViewMessage {
    if (!message || typeof message !== 'object') {
      return false
    }

    // Required fields
    if (typeof message.type !== 'string' || !message.type) {
      return false
    }

    // Optional fields type checking
    if (message.id !== undefined && typeof message.id !== 'string') {
      return false
    }

    if (message.timestamp !== undefined && typeof message.timestamp !== 'number') {
      return false
    }

    if (message.origin !== undefined && typeof message.origin !== 'string') {
      return false
    }

    return true
  }

  /**
   * Sanitize code before injection
   */
  static sanitizeCode(code: string, options: {
    allowEval?: boolean
    allowFunction?: boolean
    allowDOM?: boolean
  } = {}): string {
    let sanitized = code

    console.log("**** sanit = ", options);
    // Remove dangerous patterns if not explicitly allowed
    if (!options.allowEval) {
      sanitized = sanitized.replace(/eval\s*\(/gi, '/* eval removed */(')
    }

    if (!options.allowFunction) {
      sanitized = sanitized.replace(/Function\s*\(/gi, '/* Function removed */(')
    }

    // Remove potential XSS vectors
    sanitized = sanitized.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')

    return sanitized
  }

  /**
   * Check Content Security Policy compatibility
   */
  static checkCSP(): {
    frameAncestors: boolean
    scriptSrc: boolean
    connectSrc: boolean
  } {
    const result = {
      frameAncestors: true,
      scriptSrc: true,
      connectSrc: true
    }

    try {
      // Try to detect CSP violations by examining meta tags
      const cspMeta = document.querySelector('meta[http-equiv="Content-Security-Policy"]')
      if (cspMeta) {
        const content = cspMeta.getAttribute('content') || ''

        // Check frame-ancestors directive
        if (content.includes('frame-ancestors') && !content.includes("frame-ancestors 'self'")) {
          result.frameAncestors = false
        }

        // Check script-src directive
        if (content.includes('script-src') && !content.includes("'unsafe-inline'")) {
          result.scriptSrc = false
        }

        // Check connect-src directive
        if (content.includes('connect-src') && !content.includes("connect-src 'self'")) {
          result.connectSrc = false
        }
      }
    } catch (error) {
      console.warn('CSP check failed:', error)
    }

    return result
  }

  /**
   * Generate secure message ID
   */
  static generateMessageId(): string {
    const timestamp = Date.now().toString(36)
    const random = Math.random().toString(36).substr(2, 9)
    return `msg_${timestamp}_${random}`
  }

  /**
   * Calculate message size in bytes
   */
  static getMessageSize(message: WebViewMessage): number {
    try {
      return new Blob([JSON.stringify(message)]).size
    } catch (error) {
      // Fallback calculation
      return JSON.stringify(message).length * 2 // Rough UTF-16 estimation
    }
  }

  /**
   * Apply message filter rules
   */
  static applyMessageFilter(message: WebViewMessage, filter: MessageFilter): boolean {
    // Check allowed types
    if (filter.allowedTypes?.length) {
      if (!filter.allowedTypes.includes(message.type)) {
        return false
      }
    }

    // Check blocked types
    if (filter.blockedTypes?.length) {
      if (filter.blockedTypes.includes(message.type)) {
        return false
      }
    }

    // Check origin
    if (filter.allowedOrigins?.length && message.origin) {
      if (!this.validateOrigin(message.origin, filter.allowedOrigins)) {
        return false
      }
    }

    // Check message size
    if (filter.maxSize) {
      if (this.getMessageSize(message) > filter.maxSize) {
        return false
      }
    }

    // Custom validator
    if (filter.validator) {
      if (!filter.validator(message)) {
        return false
      }
    }

    return true
  }

  /**
   * Escape HTML content
   */
  static escapeHtml(content: string): string {
    const div = document.createElement('div')
    div.textContent = content
    return div.innerHTML
  }

  /**
   * Validate iframe sandbox permissions
   */
  static validateSandboxPermissions(sandbox: string): boolean {
    const allowedPermissions = [
      'allow-scripts',
      'allow-same-origin',
      'allow-forms',
      'allow-popups',
      'allow-modals',
      'allow-orientation-lock',
      'allow-pointer-lock',
      'allow-presentation',
      'allow-popups-to-escape-sandbox',
      'allow-top-navigation',
      'allow-top-navigation-by-user-activation'
    ]

    const permissions = sandbox.split(' ').filter(p => p.trim())
    return permissions.every(permission => allowedPermissions.includes(permission))
  }

  /**
   * Check if running in secure context (HTTPS)
   */
  static isSecureContext(): boolean {
    return window.isSecureContext || location.protocol === 'https:'
  }

  /**
   * Validate postMessage target origin
   */
  static getValidTargetOrigin(targetUrl: string, trustedOrigins: string[]): string {
    try {
      const url = new URL(targetUrl)
      const origin = url.origin

      if (this.validateOrigin(origin, trustedOrigins)) {
        return origin
      }

      throw new SecurityError('Target origin not in trusted list', { origin, trustedOrigins })
    } catch (error) {
      if (error instanceof SecurityError) {
        throw error
      }
      throw new SecurityError('Invalid target URL for postMessage', { targetUrl })
    }
  }

  /**
   * Rate limiting for message sending
   */
  static createRateLimiter(maxMessages: number, windowMs: number) {
    const messages: number[] = []

    return {
      checkLimit(): boolean {
        const now = Date.now()
        const windowStart = now - windowMs

        // Remove old messages
        while (messages.length > 0 && messages[0] < windowStart) {
          messages.shift()
        }

        // Check if under limit
        if (messages.length >= maxMessages) {
          return false
        }

        // Add current message
        messages.push(now)
        return true
      },

      getRemainingRequests(): number {
        const now = Date.now()
        const windowStart = now - windowMs
        const recentMessages = messages.filter(time => time >= windowStart)
        return Math.max(0, maxMessages - recentMessages.length)
      }
    }
  }

  /**
   * Detect potential XSS in message content
   */
  static detectXSS(content: string): boolean {
    const xssPatterns = [
      /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
      /javascript:/gi,
      /on\w+\s*=/gi,
      /<iframe\b[^>]*>/gi,
      /<object\b[^>]*>/gi,
      /<embed\b[^>]*>/gi,
      /<link\b[^>]*>/gi,
      /<meta\b[^>]*>/gi
    ]

    return xssPatterns.some(pattern => pattern.test(content))
  }
}
